    rust_spreads: "潮湿天气,叶面长时间保持湿润。",
    beanRust_sign: "叶片(多在背面)出现细小的锈褐色脓疱状斑点,周围常有浅黄色晕圈。",
    beanRust_treat: "及早摘除生锈叶片,清理作物残体,并喷施硫制剂或标签允许的杀菌剂。",
